-- Chạy toàn bộ file trong Supabase SQL Editor. Mọi thao tác ghi cần user đã đăng nhập.
create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users on delete cascade, full_name text not null default '', role text not null default 'viewer' check(role in('owner','admin','viewer')), created_at timestamptz not null default now());
create table if not exists public.materials(id uuid primary key default gen_random_uuid(), code text unique, name text not null, supplier text not null, unit text not null, specification text, created_at timestamptz not null default now());
create unique index if not exists materials_name_supplier_unique on public.materials(lower(name),lower(supplier));
create sequence if not exists public.material_code_seq start 1;
create or replace function public.set_material_code() returns trigger language plpgsql set search_path=public as $$ begin if new.code is null or btrim(new.code)='' then new.code:='NPL-'||lpad(nextval('public.material_code_seq')::text,4,'0'); end if; return new; end $$;
drop trigger if exists materials_auto_code on public.materials; create trigger materials_auto_code before insert on public.materials for each row execute function public.set_material_code();
create table if not exists public.inventory_lots(id uuid primary key default gen_random_uuid(), material_id uuid not null references public.materials, lot_number text not null, received_date date not null, expiry_date date, quantity numeric(14,3) not null check(quantity>0), remaining_quantity numeric(14,3) not null check(remaining_quantity>=0), unit_price numeric(16,2) not null check(unit_price>=0), created_at timestamptz not null default now(), unique(material_id,lot_number));
create table if not exists public.issue_vouchers(id uuid primary key default gen_random_uuid(), voucher_no text unique not null, issue_date date not null, customer text not null, order_no text not null, product text not null, status text not null default 'draft' check(status in('draft','posted','void')), total_amount numeric(18,2) not null default 0, created_by uuid not null default auth.uid() references auth.users, created_at timestamptz not null default now(), posted_at timestamptz, voided_at timestamptz);
create table if not exists public.issue_lines(id uuid primary key default gen_random_uuid(), voucher_id uuid not null references public.issue_vouchers on delete cascade, material_id uuid not null references public.materials, requested_quantity numeric(14,3) not null check(requested_quantity>0));
create table if not exists public.inventory_movements(id uuid primary key default gen_random_uuid(), voucher_id uuid not null references public.issue_vouchers, line_id uuid not null references public.issue_lines, lot_id uuid not null references public.inventory_lots, quantity numeric(14,3) not null check(quantity>0), unit_price numeric(16,2) not null, created_at timestamptz not null default now());
create or replace function public.can_edit() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from profiles where id=auth.uid() and role in('owner','admin'))$$;
create or replace function public.post_issue(p_voucher uuid,p_manual_lots jsonb default '{}'::jsonb) returns void language plpgsql security definer set search_path=public as $$ declare v record;l record;need numeric;take numeric;chosen uuid;total numeric:=0;begin if not can_edit() then raise exception 'Không có quyền';end if;select * into v from issue_vouchers where id=p_voucher for update;if v.status<>'draft' then raise exception 'Phiếu không ở trạng thái nháp';end if;for l in select * from issue_lines where voucher_id=p_voucher loop need:=l.requested_quantity;chosen:=nullif(p_manual_lots->>l.id::text,'')::uuid;for r in select * from inventory_lots where material_id=l.material_id and remaining_quantity>0 and (chosen is null or id=chosen) order by received_date,id for update loop take:=least(need,r.remaining_quantity);update inventory_lots set remaining_quantity=remaining_quantity-take where id=r.id;insert into inventory_movements(voucher_id,line_id,lot_id,quantity,unit_price) values(p_voucher,l.id,r.id,take,r.unit_price);need:=need-take;total:=total+take*r.unit_price;exit when need=0;end loop;if need>0 then raise exception 'Không đủ tồn cho nguyên liệu %',l.material_id;end if;end loop;update issue_vouchers set status='posted',total_amount=total,posted_at=now() where id=p_voucher;end$$;
create or replace function public.void_issue(p_voucher uuid) returns void language plpgsql security definer set search_path=public as $$declare v record;m record;begin if not can_edit() then raise exception 'Không có quyền';end if;select * into v from issue_vouchers where id=p_voucher for update;if v.status<>'posted' then raise exception 'Chỉ hủy phiếu đã ghi nhận';end if;for m in select * from inventory_movements where voucher_id=p_voucher for update loop update inventory_lots set remaining_quantity=remaining_quantity+m.quantity where id=m.lot_id;end loop;update issue_vouchers set status='void',voided_at=now() where id=p_voucher;end$$;
revoke all on function public.post_issue(uuid,jsonb),public.void_issue(uuid) from public;grant execute on function public.post_issue(uuid,jsonb),public.void_issue(uuid) to authenticated;
alter table public.profiles enable row level security;alter table public.materials enable row level security;alter table public.inventory_lots enable row level security;alter table public.issue_vouchers enable row level security;alter table public.issue_lines enable row level security;alter table public.inventory_movements enable row level security;
do $$declare t text;begin foreach t in array array['materials','inventory_lots','issue_vouchers','issue_lines','inventory_movements'] loop execute format('create policy %I on public.%I for select to authenticated using (auth.uid() is not null)',t||'_read',t);execute format('create policy %I on public.%I for insert to authenticated with check (public.can_edit())',t||'_insert',t);execute format('create policy %I on public.%I for update to authenticated using (public.can_edit()) with check (public.can_edit())',t||'_update',t);end loop;end$$;
create policy profiles_self_read on public.profiles for select to authenticated using(id=auth.uid());
grant usage on schema public to authenticated;grant select,insert,update on public.materials,public.inventory_lots,public.issue_vouchers,public.issue_lines,public.inventory_movements to authenticated;grant select on public.profiles to authenticated;grant usage,select on sequence public.material_code_seq to authenticated;
